  { img: 'clf-mapa-fatimida', leg: 'Map of the Fatimid Caliphate.' },
  { img: 'clf-mongois-bagdade', leg: 'Siege of Baghdad in 1258, Persian miniature from a work by Rashid al-Din.' }
